#include <iostream>
using namespace std;

const int V = 5;

void addEdge(int adj[][V], int u, int v) {
    adj[u][v] = 1;
    adj[v][u] = 1;
}

int main() {
    int adj[V][V] = {};
    addEdge(adj, 0, 1);
    addEdge(adj, 0, 2);
    addEdge(adj, 1, 3);
    addEdge(adj, 2, 3);
    addEdge(adj, 3, 4);
    int u = 3;
    cout << "Neighbours of " << u << ":";
    for (int v = 0; v < V; v++) {
        if (adj[u][v] == 1) {
            cout << " " << v;
        }
    }
    cout << endl;
    return 0;
}
